public int findLargestSubstring(List<String> strings) {
  int maxLength = 0;
  for (String string : strings) {
    int length = string.length();
    if (length > maxLength) {
      maxLength = length;
    }
    for (String inverse : strings) {
      if (string.equals(inverse)) {
        continue;
      }
      if (string.contains(inverse) || inverse.contains(string)) {
        return maxLength;
      }
    }
  }
  return maxLength;
}

