public static int countOilDeposits(char[][] grid) {
    // Initialize a set to store the unique oil deposits
    Set<Integer> oilDeposits = new HashSet<>();

    // Iterate over the rows and columns of the grid
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell contains an oil pocket, add it to the set
            if (grid[i][j] == '@') {
                oilDeposits.add(i * grid[i].length + j);
            }
        }
    }

    // Return the number of unique oil deposits
    return oilDeposits.size();
}

