def minOperations(n):
    # Initialize the array
    arr = [0] * n
    for i in range(n):
        arr[i] = (2 * i) + 1

    # Initialize the minimum number of operations
    min_operations = 0

    # Loop until all elements in arr are equal
    while not all(x == arr[0] for x in arr):
        # Find the first pair of indices x and y where arr[x] != arr[y]
        for x in range(n):
            for y in range(x + 1, n):
                if arr[x] != arr[y]:
                    break
            else:
                continue
            break

        # Select the indices x and y and perform an operation
        arr[x] -= 1
        arr[y] += 1
        min_operations += 1

    return min_operations

