    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    // Initialize the minimum number of operations to 0
    int minOperations = 0;
    // Loop until all elements in the array are equal
    while (arr.length > 0) {
        // Find the index of the maximum element
        int maxIndex = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] > arr[maxIndex]) {
                maxIndex = i;
            }
