        // Find the index of the minimum element
        int minIndex = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < arr[minIndex]) {
                minIndex = i;
            }
        }
        // Add the difference between the maximum and minimum elements to the minimum number of operations
        minOperations += arr[maxIndex] - arr[minIndex];
        // Set the maximum element to the minimum element
        arr[maxIndex] = arr[minIndex];
    }
    // Return the minimum number of operations
    return minOperations;
}

