public String getSmallestString(int n, int k) {
    /*
    We will use a greedy approach, starting with the smallest letter, and try to distribute the remaining value among the remaining letters.
    */

    if (n == 1) {
      return "" + (char)(k - 1 + 'a');
    }

    String smallestString = "";
    int remainingValue = k;
    for (int i = 0; i < n - 1; i++) {
      int charsRemaining = n - i - 1;
      int maxValueForChar = Math.min(26, remainingValue - charsRemaining + 1);
      int valueForChar = Math.max(1, Math.min(remainingValue - charsRemaining, charsRemaining));
      char c = (char)(valueForChar - 1 + 'a');
      smallestString += c;
      remainingValue -= valueForChar;
    }
    smallestString += (char)(remainingValue - 1 + 'a');
    return smallestString;
  }

