public static double calculateProbability(int n) {
        // Initialize the probability as 1.0
        double probability = 1.0;
        int seat1 = 1;
        int seat2 = 1;

        // Loop through the remaining passengers
        for (int i = 1; i <= n - 1; i++) {
            // Generate a random number between 1 and 100
            int random = (int) (Math.random() * 100.0);

            // If the random number is odd, passenger i takes seat i
            if (random % 2 == 0) {
                seat1 = i;
            }

            int[] seats = {seat1, seat2};

            // Calculate the probability of the last passenger sitting in their seat
            double currentProbability = (double) 1 / (double) seats.length;

            // Update the overall probability
            probability *= currentProbability;
        }

        return probability;
    }

