public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // If i is a perfect square, add it to the list
        if (i * i == n) {
            perfectSquares.add(i);
        }
    }

    // Initialize a variable to store the minimum number of perfect square numbers
    int minNum = Integer.MAX_VALUE;

    // Iterate over the permutations of the perfect square numbers
    for (int i = 0; i < perfectSquares.size(); i++) {
        // Calculate the sum of the current permutation
        int sum = 0;
        for (int j = i; j < perfectSquares.size(); j++) {
            sum += perfectSquares.get(j);
        }

        // If the sum is equal to n, update the minimum number of perfect square numbers
        if (sum == n) {
            minNum = Math.min(minNum, perfectSquares.size() - i);
        }
    }

    // Return the minimum number of perfect square numbers
    return minNum;
}

