    int min = Integer.MAX_VALUE;
    int count = 0;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int diff = n - i * i;
        if (diff == 0) {
            return count + 1;
        } else if (diff > 0 && diff < min) {
            min = diff;
            count++;
        }
    }
    return count;
}

